 // céu realista: nuvens e poluição atmosférica suave
 ctx.save();ctx.globalAlpha=.16;for(let i=0;i<9;i++){let x=(i*211-roadOffset*.018)%(W+350)-175,y=H*(.055+(i%4)*.055);let cg=ctx.createRadialGradient(x,y,4,x,y,96);cg.addColorStop(0,'#eef2ef');cg.addColorStop(.55,'rgba(210,218,216,.55)');cg.addColorStop(1,'rgba(180,190,192,0)');ctx.fillStyle=cg;ctx.beginPath();ctx.arc(x,y,96,0,Math.PI*2);ctx.fill()}ctx.restore();
 let sx=W*.74,sy=H*.16;let sg=ctx.createRadialGradient(sx,sy,2,sx,sy,42);sg.addColorStop(0,'rgba(255,249,214,.95)');sg.addColorStop(.18,'rgba(255,228,169,.55)');sg.addColorStop(1,'rgba(255,205,145,0)');ctx.fillStyle=sg;ctx.beginPath();ctx.arc(sx,sy,42,0,7);ctx.fill();
