  let bw=92+(i%4)*24,bh=H*(.13+(i%5)*.028),base=horizon+H*.018;
  let facade=i%5===0?'#8b7e6b':i%5===1?'#6f7c7d':i%5===2?'#9b8d79':i%5===3?'#73766d':'#867a6d';
