function drawPerson(p){
 let q=project(p.lane,p.z);if(p.z<25||p.z>1100)return;let s=q.scale,h=106*s,x=q.x,y=q.y;
 let skin=['#c9936f','#956246','#ddb18d','#70442f','#b97854'][Math.abs(p.lane+2)%5],hair=['#241916','#49372a','#171719','#5e3d2b'][Math.abs(p.z|0)%4];
 let walk=Math.sin(p.z*.025+roadOffset*.025),coat=p.color||'#445a66';
 ctx.save();ctx.translate(x,y);
 ctx.fillStyle='rgba(0,0,0,.38)';ctx.beginPath();ctx.ellipse(4*s,4*s,26*s,7*s,-.08,0,7);ctx.fill();
 // pernas com calças, joelhos e movimento natural
 ctx.strokeStyle='#252a2e';ctx.lineCap='round';ctx.lineWidth=10*s;ctx.beginPath();ctx.moveTo(-8*s,-h*.34);ctx.lineTo((-8+walk*5)*s,-h*.08);ctx.lineTo((-11+walk*8)*s,0);ctx.moveTo(8*s,-h*.34);ctx.lineTo((8-walk*5)*s,-h*.08);ctx.lineTo((11-walk*8)*s,0);ctx.stroke();
 ctx.strokeStyle='#151719';ctx.lineWidth=5*s;ctx.beginPath();ctx.moveTo((-11+walk*8)*s,-2*s);ctx.lineTo((-18+walk*8)*s,1*s);ctx.moveTo((11-walk*8)*s,-2*s);ctx.lineTo((18-walk*8)*s,1*s);ctx.stroke();
 // tronco anatomico, luz lateral e pregas
 let cg=ctx.createLinearGradient(-18*s,-h*.78,20*s,-h*.25);cg.addColorStop(0,'rgba(255,255,255,.18)');cg.addColorStop(.25,coat);cg.addColorStop(1,'#242d31');ctx.fillStyle=cg;ctx.beginPath();ctx.moveTo(-15*s,-h*.74);ctx.quadraticCurveTo(-21*s,-h*.48,-16*s,-h*.27);ctx.lineTo(17*s,-h*.27);ctx.quadraticCurveTo(21*s,-h*.48,14*s,-h*.74);ctx.quadraticCurveTo(0,-h*.82,-15*s,-h*.74);ctx.fill();
 ctx.fillStyle='rgba(20,20,20,.25)';ctx.fillRect(-1*s,-h*.72,2*s,h*.43);
 // braços e mãos
 ctx.strokeStyle=coat;ctx.lineWidth=8*s;ctx.beginPath();ctx.moveTo(-14*s,-h*.68);ctx.quadraticCurveTo((-25-walk*3)*s,-h*.45,-20*s,-h*.25);ctx.moveTo(14*s,-h*.68);ctx.quadraticCurveTo((25+walk*3)*s,-h*.45,20*s,-h*.25);ctx.stroke();
 ctx.fillStyle=skin;ctx.beginPath();ctx.arc(-20*s,-h*.23,4.2*s,0,7);ctx.arc(20*s,-h*.23,4.2*s,0,7);ctx.fill();
 // pescoço, orelhas e cabeça
 ctx.fillStyle=skin;ctx.fillRect(-5*s,-h*.83,10*s,9*s);ctx.beginPath();ctx.arc(-13*s,-h*.91,3*s,0,7);ctx.arc(13*s,-h*.91,3*s,0,7);ctx.fill();
 ctx.beginPath();ctx.ellipse(0,-h*.92,13*s,16*s,.03,0,7);ctx.fill();
 // cabelo, sobrancelhas e olhos sutis
 ctx.fillStyle=hair;ctx.beginPath();ctx.ellipse(-1*s,-h*.99,13*s,8*s,.05,Math.PI,Math.PI*2);ctx.lineTo(12*s,-h*.94);ctx.quadraticCurveTo(8*s,-h*1.02,-13*s,-h*.96);ctx.fill();
 ctx.strokeStyle='rgba(25,20,18,.75)';ctx.lineWidth=1.2*s;ctx.beginPath();ctx.moveTo(-7*s,-h*.93);ctx.lineTo(-3*s,-h*.94);ctx.moveTo(3*s,-h*.94);ctx.lineTo(7*s,-h*.93);ctx.stroke();
 ctx.fillStyle='#1a1a18';ctx.beginPath();ctx.arc(-5*s,-h*.9,1.1*s,0,7);ctx.arc(5*s,-h*.9,1.1*s,0,7);ctx.fill();
 ctx.restore();
}

